-- GRANTs for the captured functions
-- ============================================================================
GRANT EXECUTE ON FUNCTION public.request_mpesa_deposit(numeric, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.request_mpesa_withdrawal(numeric, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_user_banned(uuid, boolean, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_delete_user(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_user_role(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.my_downline_ids() TO authenticated;
GRANT EXECUTE ON FUNCTION public.franchise_get_members() TO authenticated;
GRANT EXECUTE ON FUNCTION public.franchise_get_deposits() TO authenticated;
GRANT EXECUTE ON FUNCTION public.franchise_get_withdrawals() TO authenticated;
GRANT EXECUTE ON FUNCTION public.franchise_get_stats() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_franchise_members(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_franchise_deposits(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_franchise_withdrawals(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_franchise_stats(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_list_franchises() TO authenticated;
GRANT EXECUTE ON FUNCTION public.set_partner_float(uuid, numeric) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.request_mpesa_deposit_statuses() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.process_mpesa_deposit_statuses() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.request_mpesa_withdrawal_statuses() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.process_mpesa_withdrawal_statuses() FROM PUBLIC, anon, authenticated;

-- ============================================================================
-- Cron schedule (captured from production). Unschedule-then-schedule = idempotent.
-- ============================================================================
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'mpesa-deposit-poll-request';
SELECT cron.schedule('mpesa-deposit-poll-request', '*/2 * * * *', $$SELECT public.request_mpesa_deposit_statuses();$$);
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'mpesa-deposit-poll-process';
SELECT cron.schedule('mpesa-deposit-poll-process', '1-59/2 * * * *', $$SELECT public.process_mpesa_deposit_statuses();$$);
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'mpesa-withdrawal-poll-request';
SELECT cron.schedule('mpesa-withdrawal-poll-request', '*/2 * * * *', $$SELECT public.request_mpesa_withdrawal_statuses();$$);
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'mpesa-withdrawal-poll-process';
SELECT cron.schedule('mpesa-withdrawal-poll-process', '1-59/2 * * * *', $$SELECT public.process_mpesa_withdrawal_statuses();$$);
-- Signal, market-price, subscription, close jobs (already existed; re-asserted for completeness)
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'generate-signal-schedule';
SELECT cron.schedule('generate-signal-schedule', '0 23,3,7,11,15,19 * * *', $$SELECT public.generate_signal();$$);
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'close-signals-schedule';
SELECT cron.schedule('close-signals-schedule', '* * * * *', $$SELECT public.close_due_signals();$$);
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'request-market-prices-schedule';
SELECT cron.schedule('request-market-prices-schedule', '*/5 * * * *', $$SELECT public.request_market_prices();$$);
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'process-market-prices-schedule';
SELECT cron.schedule('process-market-prices-schedule', '1,6,11,16,21,26,31,36,41,46,51,56 * * * *', $$SELECT public.process_market_prices();$$);
SELECT cron.unschedule(jobid) FROM cron.job WHERE jobname = 'process-subscriptions-schedule';
SELECT cron.schedule('process-subscriptions-schedule', '0 * * * *', $$SELECT public.process_all_subscriptions();$$);
